func TestAttemptSuccessAndFailureFlow(t *testing.T) {
	_, handler := newTestRouter(t)
	create := do(handler, http.MethodPost, "/api/v1/jobs", `{"job":"j","schedule":"0 * * * *","maxRetries":2}`)
	if create.Code != http.StatusCreated {
		t.Fatalf("create: %d %s", create.Code, create.Body.String())
	}

	// First failure: retries becomes 1, next is attemptedAt + 2 minutes.
	fail1 := do(handler, http.MethodPost, "/api/v1/jobs/j/attempts",
		`{"sequence":1,"outcome":"failure","attemptedAt":"2026-10-03T10:00:00Z"}`)
	if fail1.Code != http.StatusOK {
		t.Fatalf("fail1 status = %d %s", fail1.Code, fail1.Body.String())
	}
	state := decodeJob(t, fail1)
	if state.FailureRetries != 1 || state.Paused {
		t.Fatalf("after first failure: %+v", state)
	}
	if state.NextRunAt != "2026-10-03T10:02:00Z" {
		t.Fatalf("next = %s, want +2m", state.NextRunAt)
	}

	// Second failure: retries becomes 2 (== max), job pauses, next stays at +2m.
	fail2 := do(handler, http.MethodPost, "/api/v1/jobs/j/attempts",
		`{"sequence":2,"outcome":"failure","attemptedAt":"2026-10-03T10:05:00Z"}`)
	if fail2.Code != http.StatusOK {
		t.Fatalf("fail2 status = %d %s", fail2.Code, fail2.Body.String())
	}
	state = decodeJob(t, fail2)
	if !state.Paused || state.FailureRetries != 2 {
		t.Fatalf("after exhaustion: %+v", state)
	}
	if state.NextRunAt != "2026-10-03T10:02:00Z" {
		t.Fatalf("exhaustion must not advance schedule, next = %s", state.NextRunAt)
	}
	if len(state.Attempts) != 2 {
		t.Fatalf("attempts = %d, want 2", len(state.Attempts))
	}

	// Attempts while paused are refused before sequence checks.
	pausedAttempt := do(handler, http.MethodPost, "/api/v1/jobs/j/attempts",
		`{"sequence":99,"outcome":"success","attemptedAt":"2026-10-03T10:06:00Z"}`)
	if pausedAttempt.Code != http.StatusConflict || decodeAPIError(t, pausedAttempt).Error.Code != "job_paused" {
		t.Fatalf("paused attempt = %d %s", pausedAttempt.Code, pausedAttempt.Body.String())
	}

	// Resume, then success resets retries and recomputes from attemptedAt.
	resume := do(handler, http.MethodPost, "/api/v1/jobs/j/pause", `{"paused":false}`)
	if resume.Code != http.StatusOK {
		t.Fatalf("resume = %d", resume.Code)
	}
	success := do(handler, http.MethodPost, "/api/v1/jobs/j/attempts",
		`{"sequence":3,"outcome":"success","attemptedAt":"2026-10-03T10:30:00Z"}`)
	if success.Code != http.StatusOK {
		t.Fatalf("success = %d %s", success.Code, success.Body.String())
	}
	state = decodeJob(t, success)
	if state.FailureRetries != 0 || state.Paused {
		t.Fatalf("after success: %+v", state)
	}
	if state.NextRunAt != "2026-10-03T11:00:00Z" {
		t.Fatalf("next = %s, want next hourly tick after attempt", state.NextRunAt)
	}
	if len(state.Attempts) != 3 {
		t.Fatalf("attempts = %d, want 3", len(state.Attempts))
	}
}

