func TestAttemptsRetryAndPauseFlow(t *testing.T) {
	router, _ := newTestRouter(t)

	rec := doJSON(t, router, http.MethodPost, "/api/v1/jobs", `{"job":"j","schedule":"0 * * * *","maxRetries":1}`)
	if rec.Code != http.StatusCreated {
